// Supplement to the pinned budget-19 omission checker.
// Each lifted prime-power digit requires p-1 distinct competitors.
const fs = require("node:fs");
const frozenWeights = JSON.parse(fs.readFileSync(process.argv[3], "utf8"));
const budget = 21;
const cutoff = 5160960;
const ceilDiv = (a,b) => (a+b-1n)/b;

function highPeriods(maxWeight, lower) {
  const out = [];
  const prime = [2,3,5,7,11,13,17,19];
  function visit(i, value, left, charges) {
    if(i === prime.length) {
      if(value > lower) out.push([value,maxWeight-left,charges]);
      return;
    }
    const p = prime[i];
    for(let power = 1; left >= 0; left -= p-1, power *= p) {
      visit(i+1,value*power,left,charges);
      charges = charges.concat([[power*p,p-1]]);
    }
  }
  visit(0,1,maxWeight,[]);
  return out;
}

function privateModel(step, parity, selected, specs, weights) {
  const u = z => step === 2 ? z : parity+2*z;
  const fixed = extras.filter(([,,q]) => selected.includes(q)).map(([a,d]) => {
    const m = d/gcd(d,step/2);
    const b = Array.from({length:m},(_,z)=>z).find(z=>u(z)%d===a);
    assert(b !== undefined, "incompatible fixed branch");
    return [b,m];
  });
  const L = fixed.reduce((l,[,d])=>lcm(l,d),105);
  const D = Array.from({length:L},(_,z)=>z).filter(z=>H.includes(u(z)%105)&&!fixed.some(([b,d])=>z%d===b));
  const at = z => BigInt(weights[H.indexOf(u(z)%105)]);
  const demand = D.reduce((sum,z)=>sum+at(z),0n)*periodScale;
  const h0 = Math.floor(cutoff/(L*step));
  const periods = highPeriods(budget-1,h0);
  const powers = new Set([1,...periods.flatMap(([, ,ch])=>ch.map(([power])=>power))]);
  const cap = new Map();
  for(const power of powers) {
    const high = ceilDiv(demand,BigInt(Math.ceil(31/power)*power));
    cap.set(power,Array(4).fill(high).concat(specs.map(()=>null)));
  }
  let highMax = [0n,1n];
  for(const g of divisors(L)) {
    const residue = Array(g).fill(0n);
    for(const z of D) residue[z%g] += at(z);
    const best = minimum(residue);
    const den = BigInt(Math.floor(cutoff/(g*step))+1);
    if(best*highMax[1]>highMax[0]*den) highMax=[best,den];
    for(let m=1;m<=30;m++) {
      const h=g*m;
      if(gcd(h,L)!==g || h===11 || h===13 || !hasFree(h,step))continue;
      const j=specs.indexOf(h), group=j<0?flags(h):4+j;
      const value=best*(periodScale/BigInt(m));
      for(const power of divisors(m)) {
        const ar=cap.get(power);
        if(ar && (ar[group]===null || ar[group]<value)) ar[group]=value;
      }
    }
  }
  return {demand,periods,cap,highMax,L};
}

function analyze(scope, cases, cert) {
  const {step,parity,selected}=scope;
  const specs=(step===2?[33,17,25,39]:[20,33,22,17]);
  const {demand,periods,cap,highMax:[highNum,highDen],L} =
    privateModel(step,parity,selected,specs,cert.weights);
  const counts={full:cases.length,noHighSlot:0,massOnly:0,digit:0,periodsChecked:0,survivors:[]};
  const costs=new Map();
  for(const row of cases) {
    if(!row.left) { counts.noHighSlot++; continue; }
    const {j,k,used,left}=row;
    const factors=mulFlags(j,k), get=(a,i)=>a===null?null:a*factors[i];
    const scaleCaps=items=>items.map((a,i)=>get(a,i<4?i:flags(specs[i-4])));
    const selection=costs.get(j+','+k)??new Map([...cap].map(([power,values])=>[power,scaleCaps(values)]));
    costs.set(j+','+k,selection);
    const base=selection.get(1), generic=minimum(base.slice(0,4));
    const competitorBound=BigInt(left-1)*generic+used.reduce((sum,n,i)=>sum+BigInt(n)*(base[4+i]??0n),0n);
    const targetBound=143n*highNum*periodScale;
    const totalBound=competitorBound*highDen+targetBound;
    const required=demand*factors[0]*highDen;
    if(totalBound<required) { counts.massOnly++; continue; }
    const penalties=new Map();
    for(const [power,values] of selection) {
      if(power===11 || power===13){penalties.set(power,0n);continue;}
      const possible=[];
      if(left>1)possible.push(generic-minimum(values.slice(0,4)));
      used.forEach((n,i)=>{ if(n && values[4+i]!==null) possible.push(base[4+i]-values[4+i]); });
      penalties.set(power,possible.reduce((a,b)=>a===null||b<a?b:a,null));
    }
    const remaining = j+k+left+used.reduce((a,b)=>a+b,0)-1;
    let survivor=null;
    for(const [m,weight,charges] of periods) {
      if(weight>remaining)continue;
      let penalty=0n, feasible=true;
      for(const [power,count] of charges) {
        const loss=penalties.get(power);
        if(loss===null){feasible=false;break;}
        penalty+=BigInt(count)*loss;
      }
      counts.periodsChecked++;
      if(feasible && totalBound-penalty*highDen>=required) {
        survivor={m,weight,loss:frac(totalBound-penalty*highDen,required).map(String)};
        break;
      }
    }
    if(!survivor)counts.digit++;
    else counts.survivors.push({row,survivor});
  }
  return {...scope,L,...counts};
}

const output=[];
for(const [step,parity] of [[2,0],[4,0],[4,1]]){
 const r=runBudget(budget,step,parity);
 for(const Q of Map.groupBy(r.trouble,q=>q.selected.join(',')).values()){
  const selected=Q[0].selected, scope={step,parity,selected,coarseCases:r.leaves};
  const cert=frozenWeights.find(w=>w.step===step&&w.parity===parity&&w.selected.join()===selected.join()&&w.extra.length===Number(step===4));
  assert(cert&&cert.weights.length===H.length&&cert.weights.every(w=>Number.isSafeInteger(w)&&w>=0)&&cert.weights.some(Boolean),'valid weights');
  const cases=step===4?Q.flatMap(q=>Array.from({length:Math.min(q.left,5)+1},(_,k)=>({...q,used:[...q.used,k],left:q.left-k}))):Q;
  output.push(analyze(scope,cases,cert));
 }
}
console.log(JSON.stringify(output,null,2));

