const B=[0,3,5,8,10,15,21,23,26,28,30,31,33];
const gcd=(a,b)=>b?gcd(b,a%b):a;
const lcm=(a,b)=>a/gcd(a,b)*b;
const digitsCache = new Map();
function digits(n) {
  if (!digitsCache.has(n)) {
    const original=n, powers=[];
    let weight=0;
    for(let p=2;p<=n;p++) {
      for(let power=p;n%p===0;power*=p,n/=p) {
        powers.push([power,p-1]);
        weight+=p-1;
      }
    }
    digitsCache.set(original,{powers,weight});
    return {powers,weight};
  }
  return digitsCache.get(n);
}
