function gcdBig(a,b){return b?gcdBig(b,a%b):a;}
const scale=m0.map(BigInt).reduce((a,b)=>a*b/gcdBig(a,b),1n);
const maxBig=values=>values.reduce((a,b)=>a>b?a:b,0n);
const eligible=h0.filter(h=>h>=9&&h!==10);
const fixed=[[2,1],[3,1],[4,2]];
const rows=[0,1,2,3,5];
const bits=(mask,arr)=>arr.filter((_,i)=>(mask>>i)&1);
const assert=(test,message)=>{if(!test)throw Error(message);};
