  function descend(rows, residue, stride) {
    if(offsets.length===limit || rows.some(([m])=>m===1))return;
    if(!rows.length) {
      for(let x=residue;x<period&&offsets.length<limit;x+=stride)offsets.push(x);
      return;
    }
    // The least prime surviving in a modulus always divides the branch period.
    const prime=Math.min(...rows.map(([m])=>factors(m)[0][0]));
    assert(period%(stride*prime)===0,'CRT lift exceeds the joint period');
    const prepared=rows.map(([m,r])=>[m,r,m%prime?inverseMod(prime,m):null]);
    for(let digit=0;digit<prime&&offsets.length<limit;digit++) {
      const next=[];
      for(const [m,r,inv] of prepared) {
        if(inv!==null)next.push([m,Number((BigInt(mod(r-digit,m))*BigInt(inv))%BigInt(m))]);
        else if(r%prime===digit)next.push([m/prime,(r-digit)/prime]);
      }
      descend(next,residue+stride*digit,stride*prime);
    }
  }
  descend(classes,0,1);
  return offsets;
}

function missingPoints(D,L,P,classes,add) {
  let count=0;
