  if(count)return count;
  for(const d of D) {
    const rows=[];
    for(const [p,b] of classes) {
      const g=gcd(p,L), m=p/g;
      if((b-d)%g)continue;
      const r=m===1?0:Number(BigInt(mod((b-d)/g,m))*BigInt(inverseMod(L/g,m))%BigInt(m));
      rows.push([m,r]);
    }
    const uncovered=firstUncoveredOffsets(rows,P/L,8-count);
    for(const z of uncovered){add(d+L*z);count++;}
    if(count===8)break;
