"""Normalized high-period templates for split Riesel R4 tails."""
from collections import Counter
from itertools import product
from math import gcd
import json


def templates():
    rows = []
    for a, b, c in product(range(10), range(3), range(2)):
        odd = 3**a * 5**b * 7**c
        weight = 2*a + 4*b + 6*c
        for common in (1, 5, 7, 35):
            if gcd(common*odd, 35) != common:
                continue
            cost = weight
            while 16*common*odd > 35*2**cost:
                rows.append((odd, common, cost, cost-weight))
                cost += 1
    return sorted(rows)


if __name__ == "__main__":
    rows = templates()
    print(json.dumps({
        "odd_parts_before_gcd_filter": sum(
            2**(2*a+4*b+6*c) < 16*3**a*5**b*7**c
            for a, b, c in product(range(10), range(3), range(2))
        ),
        "count": len(rows),
        "common_divisors": dict(sorted(Counter(row[1] for row in rows).items())),
        "unused_slots": dict(sorted(Counter(row[3] for row in rows).items())),
        "largest_cost": max(row[2] for row in rows),
        "rows": rows,
    }, separators=(",", ":")))
